package net.civeira.phylax.feature.observe.observedalert.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class SummaryVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property summary of observed alert ")
  void test_summary_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> SummaryVO.tryFrom(null));
    Assertions.assertEquals("one", SummaryVO.from("one").getSummary());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> SummaryVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", SummaryVO.from("one").toString());
  }
}
